# # Partial derivatives # $fx = $f->D('x'); $fy = $f->D('y');
# # A point (x,y) = (a,b) # ($a,$b) = (random(1,5,1),random(1,5,1));
$fab = $f -> eval(x=>$a,y=>$b) -> reduce;
$fxab = $fx -> eval(x=>$a,y=>$b) -> reduce; $fyab = $fy -> eval(x=>$a,y=>$b) -> reduce;
$studentplane = Compute("$fab + $fx*(x - $a) + $fy*(y - $b)")->reduce; $tangentplane = Formula("$fab + ($fxab)*(x-$a) + ($fyab)*(y-$b)") -> reduce;
########## # Part A
