##DESCRIPTION
##  Green's theorem, path-dependent vector fields, non-conservative vector fields
##ENDDESCRIPTION


## DBsubject(Calculus - multivariable)
## DBchapter(Fundamental theorems)
## DBsection(Green's theorem)
## Date(10/31/09)
## Institution(Fort Lewis College)
## Author(Paul Pearson)
## Level(2)
## MO(1)
## TitleText1('Calculus')
## AuthorText1('Hughes-Hallett')
## EditionText1('4')
## Section1('18.4')
## Problem1('')
## TitleText2('Calculus')
## AuthorText2('Hughes-Hallett')
## EditionText2('5')
## Section2('18.4')
## Problem2('')
## KEYWORDS('Greens theorem','path-dependent vector fields','non-conservative vector fields')


DOCUMENT();

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "contextFraction.pl",
  "PGgraphmacros.pl",
  "unionTables.pl",
  "VectorField2D.pl",
  "PGcourse.pl"
);

TEXT(beginproblem());

$refreshCachedImages=1;

#####################################
#  Setup

Context("Numeric")->variables->are(x=>"Real",y=>"Real");

$a = random(2,4,1);
$b = random(2,4,1);
$c = random(2,5,1);
while ($c==$b) { $b = random(2,4,1); }

$F = "($a x - $b y) \vec{i} + $c x \vec{j}";

$r = random(2,4,1);
$rr = $r * $r;

$d = list_random(6,4,3);

if ($d == 6) {

  $answer = Compute("($b + $c) pi $rr / 12"); 
  $x = $r * sqrt(3)/2;
  $y = $r/2;

} elsif ($d == 4) {

  $answer = Compute("($b + $c) pi $rr / 8");
  $x = $r / sqrt(2);
  $y = $r / sqrt(2);

} else {

  $answer = Compute("($b + $c) pi $rr / 6");
  $x = $r/2;
  $y = $r * sqrt(3)/2;

}


#######################
#  create graphs


foreach my $i (0) {
  $gr[$i] = init_graph(-1,-1,5,5,grid=>[6,6],axes=>[0,0],pixels=>[400,400]);
  $gr[$i]->lb('reset');
  foreach my $j (1..4) {
    $gr[$i]->lb( new Label(-0.7,  $j, $j,'black','center','middle'));
#    $gr[$i]->lb( new Label(-0.7, -$j,-$j,'black','center','middle'));
    $gr[$i]->lb( new Label(  $j,-0.7, $j,'black','center','middle'));
#    $gr[$i]->lb( new Label( -$j,-0.7,-$j,'black','center','middle'));
  }
  $gr[$i]->lb( new Label(4.7,0.2,'x','black','center','middle'));
  $gr[$i]->lb( new Label(0.2,4.7,'y','black','center','middle'));

  VectorField2D(
  graphobject => $gr[$i],
  Fx => Formula("$a x - $b y"),
  Fy => Formula("$c x"),
  xvar => "x",
  yvar => "y",
  xmin => -1,
  xmax =>  5,
  ymin => -1,
  ymax =>  5,
  xsamples => 12,
  ysamples => 12,
  vectorcolor => "blue",
  vectorscale => 0.03,
  vectorthickness => 2,
  );

}


############################
add_functions($gr[0],
"sqrt($rr-x^2) for x in <$x,$r> using color:red and weight:2",
);

$gr[0]->moveTo(0,0);
$gr[0]->lineTo($r,0,"red",3);

$gr[0]->moveTo(0,0);
$gr[0]->lineTo($x,$y,"red",3);

$gr[0]->stamps( closed_circle(0,0,'red') );
$gr[0]->stamps( closed_circle($r,0,'red') );
$gr[0]->stamps( closed_circle($x,$y,'red') );

$rd2 = $r / 2;

$gr[0]->moveTo($rd2,0);
$gr[0]->arrowTo($rd2+0.1,0,"red",3);


foreach my $i (0) {
  $fig[$i] = image(insertGraph($gr[$i]),width=>"400",height=>"400",tex_size=>"700");
}



########################################
#  Main text

BEGIN_TEXT
Suppose \[ \vec{F}(x,y) = $F \] and \( C \) is the 
counter-clockwise oriented sector of a circle centered
at the origin with radius \( $r \) and central angle
\( \pi / $d \).
Use Green's theorem to calculate the 
circulation of \( \vec{F} \) around \( C \).
$BR
$BR
Circulation = 
\{ans_rule(40)\}
$BR
$fig[0]
$BR
(Click on graph to enlarge)
END_TEXT


###############################################
#  Answer evaluation

$showPartialCorrectAnswers = 1;

ANS($answer->cmp() );

$cb = $c + $b;
Context("Fraction");
$aa = Compute("$cb*($r^2)/(2*$d)");
Context()->texStrings;
BEGIN_SOLUTION
$PAR SOLUTION $BR $BR
Let \(D\) be the region enclosed by the curve \(C\). $BR
First note that the curve has a positive orientation. We will use Green's Theorem.
We have \( P = $a x - $b y, \; Q = $c x \), therefore
\[ \frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y} =$c+ $b = $cb .\]
Hence, Green's Theorem implies $BR
\( \begin{array}{lcl} \int_{C} \vec{F} \cdot  d\vec{r}& = & 
\iint_D \left( \frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y} \right) dA
\\ &=& \iint_D $cb dA  
\\ & = & $cb \int_0^{\pi/$d} \int_0^{$r} r \, dr \, d\theta \quad \text{[Using polar coordinates]}
\\& = & $cb \left(\frac{\pi}{$d}\right) \left(\frac{ $r^2}{2}\right)
\\&=& $aa \pi
\end{array}\)
END_SOLUTION

ENDDOCUMENT();

li.p:
If S_1 is a rectangle with area 1 and S_2
is a rectangle with area 2, then 
\displaystyle 2 \iint_{S_1} \vec{F} \cdot d\vec{A} 
= \iint_{S_2} \vec{F} \cdot d\vec{A}

statement.p:
Use the divergence theorem to calculate the flux of 
the vector field \vec{F}(x,y,z) = x^3 \vec{i}
+ y^3 \vec{j} + z^3 \vec{k}
out of the closed, outward-oriented surface S 
bounding the solid x^2 + y^2 \leq 25, \ 
0 \leq z \leq 4.

static.solution:
\mbox{div}\,{\vec{F}} = 10x + 8y + 8z. So, if W is the interior of the box, we have \int_{S}\vec{F} \cdot d\vec{A} = \int_{W}(10x + 8y + 8z)dV = \int_{0}^{2}\int_{2}^{3}\int_{0}^{3}(10x + 8y + 8z)dz\,dy\,dx. Integrating through each of the integrals in turn, we have \int_{S}\vec{F} \cdot d\vec{A} = \int_{0}^{2}\int_{2}^{3} 10x\,z + 8y\,z + 4z^{2}\bigg|_{z=0}^{z=3}\, dy\,dx = \int_{0}^{2}\int_{2}^{3} 30 x + 24 y + 36\,dy\,dx = \int_{0}^{2} 30 x y + 12 y^2 + 36 y\bigg|_{y=2}^{y=3}\,dx = \int_{0}^{2} 30 x + 60 + 36\, dx = 15 x^2 + 60 x + 36 x\bigg|_{x=0}^{x=2} = 252.
Finding flux directly, note that on the faces x=2 and x=0 the normal vectors to the surfaces are \vec i and -\vec i respectively, so that \vec F\cdot d\vec A = \pm 5x^{2}\,dy\,dz (where x is evaluated at 2 or 0), and similarly on y = 3 and y = 2, and z = 3 and z = 0, \vec F\cdot d\vec A = \pm 4y^{2}\,dx\,dz and \vec F\cdot d\vec A = \pm 4z^{2}\,dx\,dy, respectively. Thus on x = 0 and z = 0 the flux is zero. On the remaining faces, we have
(1) On x = 2, \vec F\cdot d\vec A = \int_{2}^{3}\int_{0}^{3}\,20\,dz\,dy = 60;
(2) On y = 3, \vec F\cdot d\vec A = \int_{0}^{2}\int_{0}^{3}\,36\,dz\,dx = 216;
(3) On y = 2, \vec F\cdot d\vec A = \int_{0}^{2}\int_{0}^{3}\,16\,dz\,dx = -96; and
(4) On z = 3, \vec F\cdot d\vec A = \int_{0}^{2}\int_{2}^{3}\,36\,dy\,dx = 72. Thus the total flux is the sum of these, \vec F\cdot d\vec A = 252.
